from pydantic import BaseModel, ConfigDict

class TodoBase(BaseModel):
    title: str
    description: str | None = None
    completed: bool | None = False
    
class TodoCreate(TodoBase):
    pass

# To send Todo response to the client, we need to create a new class that inherits from TodoBase and adds an id field. This is because the id field is generated by the database and is not part of the request body when creating a new todo item.
class Todo(TodoBase):
    id: int
    class Config:
        orm_mode = True  # This tells Pydantic to read data from the SQLAlchemy model instance.
        
    # model_config = ConfigDict(from_attributes=True)  # This tells Pydantic to read data from the SQLAlchemy model instance.